-- ============================================================
-- znty-rrs 定时任务配置 - 演示数据
-- MySQL version: 8.0.33
-- 说明：预置已知任务配置；task_code 须与 RrsScheduledTask 实现类一致
-- Demo 行与 id 按业务确认顺序排列；全部任务默认关闭调度；
-- 新增任务不得只改代码，须按依赖调整 cron 并更新需求文档。
-- ============================================================

USE `znty_rrs`;
SET NAMES utf8mb4;

-- ----------------------------------------------------------------------------
-- 清空业务表
-- ----------------------------------------------------------------------------
-- 清空定时任务执行历史
DELETE FROM `sys_scheduled_task_run_log`;
-- 清空定时任务配置（操作审计）
DELETE FROM `sys_scheduled_task_evt`;
-- 清空定时任务配置
DELETE FROM `sys_scheduled_task`;

-- ----------------------------------------------------------------------------
-- 定时任务配置样例（19 条）
-- ----------------------------------------------------------------------------
INSERT INTO `sys_scheduled_task` (
    `id`, `task_code`, `task_name`, `description`, `cron_expression`, `schedule_enabled`,
    `param_json`, `last_run_status`, `last_run_message`, `last_run_time`, `last_affected_count`,
    `last_duration_ms`, `last_trigger_type`, `is_deleted`, `crte_time`, `updt_time`
) VALUES
-- cron 执行顺序：临时代码多时点替换 → 22:00 同步债券类型 → 22:40 再替换 → 再清到期 → 先改主体（先出后入）→ 再同步旗下债（先入后出）
-- 临时代码 04:40/08:40/09:40/13:40/18:40/22:40 → 22:00 债券类型变更 → 23:00 到期债券出池 → 23:05 CRMW到期出 → 23:10 外评主体出 → 23:15 外评主体入 → 23:21 旗下债券补入 → 次日06:00观察名单及联动同步
(13, 'bond_temp_code_replace', '债券临时代码替换（仅债券）', '1. Demo 每天 04:40、08:40、09:40、13:40、18:40、22:40 执行，无需扩展参数，默认关闭调度。\n2. 扫描 rrs_temp_security_code 中 status=temporary 且已由外部数据补齐 security_code 的记录。\n3. 正式名称、市场、类型以 rrs_securityinfo 正式主数据为准。\n4. 普通池按同券市场代码整组转换；在途沿用原审批并补关联项，已在池临时退出后正式组统一进入。\n5. CRMW 保留凭证，标的按全部市场代码整组转换并逐码记账。\n6. 成功后登记状态改为 updated，操作来源记为 job，写入旧新码映射。失败时回滚本条转换，保留待处理登记。\n7. 本任务与 wind_code_sync 使用独立扫描入口，共用业务转换组件。', '0 40 4,8,9,13,18,22 * * ?', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(14, 'bond_security_type_change', '债券类型变更（仅债券）', '1. Demo 每天 22:00 执行，无需扩展参数，默认关闭调度。\n2. 以 rrs_securityinfo.security_type 为最新证券类型，在池状态仅同步新旧类型都属于有效债券大类的类型差异。\n3. 同步普通池证券、CRMW 标的证券及当前池状态关联的调库日志。\n4. 主档最新类型属于有效债券大类且与流水类型不同时，按证券代码补齐已审批通过且未删除的调入调出流水，池状态已一致或证券已出池时仍同步。\n5. CRMW 凭证自身类型及提交时的证券快照继续保留。\n6. 位于 18:40 临时代码替换之后、23:00 到期及主体调库任务之前，22:40 替换直接使用正式主数据类型。', '0 0 22 * * ?', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(1, 'security_expired_auto_out', '到期证券自动出池', '1. Demo 每天 23:00 执行，默认关闭调度。\n2. 将 poolIds 指定的池与投资池配置绑定本任务的池合并，Demo 为 [15]（债券禁止库）。合并后无扫描池时本轮失败。\n3. 扫描 ip_pool_status 中已生效且未删除的债券（含 ABS、CRMW），按证券代码关联 rrs_securityinfo，取证券主档摘牌日 delist_date（yyyyMMdd）。有值且早于数据库当前日期减去 maturityOffsetDays 天才进入候选。默认偏移 1 天，摘牌日早于昨天（T-2）自动出池。\n4. ip_pool_status_crmw 中的凭证与标的组合由 CRMW 到期任务扫描。\n5. 先按在池记录 ID 剔除 Excel 保护项，再跳过命中调出限制池、已出池或缺少证券编码的候选。\n6. 仅软删除成功才写业务调库记录并计入实际出池。', '0 0 23 * * ?', 0, '{"poolIds":[15],"maturityOffsetDays":1}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(2, 'crmw_expired_auto_out', 'CRMW到期自动出池', '1. Demo 每天 23:05 执行，默认关闭调度。\n2. 将 poolIds 指定的池与投资池配置绑定本任务的池合并，Demo 为 [18]（CRMW库）。合并后无扫描池时本轮失败。\n3. 扫描 ip_pool_status_crmw 中已生效且未删除的凭证与标的组合，包含 ABS 债券作为标的的组合。ip_pool_status 中的 CRMW 券由到期证券自动出池任务扫描。\n4. 按凭证代码关联 rrs_securityinfo，取凭证摘牌日 delist_date（yyyyMMdd）。有值且早于数据库当前日期减去 maturityOffsetDays 天才调出整条组合。默认偏移 1 天，凭证摘牌日早于昨天（T-2）自动出池。\n5. 凭证摘牌日未达到出池条件时，标的债券的摘牌日不触发组合出池。\n6. 按标的证券代码、凭证代码和凭证类型匹配调出限制池，命中时跳过。仅软删除成功才写业务调库记录并计入实际出池。', '0 5 23 * * ?', 0, '{"poolIds":[18],"maturityOffsetDays":1}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(3, 'company_outer_rating_not_aa_minus_auto_out', '外评非AA-及以下主体自动出池（仅主体）', '1. Demo 配置每天 23:10，默认关闭调度。\n2. 扫描目标池中已生效在池的主体。poolIds 与投资池关系配置绑定本任务的自动调出池取并集，Demo 为 [17]（黑名单质押库）。无有效认可机构或扫描池时本轮失败。\n3. 取近一年认可机构的最低外评，同档取最新。AA-及以下不出池，空评级/近一年无认可外评不出池。\n4. 黑名单质押库（17）的三个留池条件，满足任一项即留池。\n（一）主体当前已生效在债券禁止库（15）。\n（二）主体近一年认可机构的最低外评为 AA- 或更低。\n（三）主体当前已生效在重点观察名单（23）。\n三项均未命中且最低外评为 AA 及以上时，可进入出池处理。近一年认可机构的非空评级均无法识别档位时也可能成为候选。\n5. 跳过受 Excel 入池保护、命中目标池调出限制池或位于 limitPoolIds 指定池的主体。limitPoolIds 省略或为 [] 时不额外拦截。\n6. 系统直接调出主体，记录任务名称和近一年最低外评。写入失败时本轮回滚。\n7. 旗下债券由独立任务同步。', '0 10 23 * * ?', 0, '{"poolIds":[17],"limitPoolIds":[]}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(4, 'company_outer_rating_aa_minus_auto_in', '外评AA-及以下主体自动入池（仅主体）', '1. Demo 配置每天 23:15，默认关闭调度。\n2. poolIds 与投资池关系配置绑定本任务的自动调入池取并集，Demo 为 [17]（黑名单质押库）。只扫描尚未在目标池生效的主体，按主体去重。\n3. 满足任一条件即可进入候选。\n（一）主体当前已生效在债券禁止库（15）。\n（二）主体近一年认可机构的最低外评为 AA- 或更低，同档取最新。\n（三）主体当前已生效在重点观察名单（23）。\n4. AA-及以下因评级入池；空评级/近一年无认可外评不因评级入池，命中禁止库 15 或重点观察 23 时仍按相应条件入池。\n5. 跳过命中目标池调入限制池的主体；目标池为 17 时复核三项条件。未配置有效认可评级机构或扫描范围为空时，本轮失败。\n6. 主体入池直接生效，调库日志记录任务名称及命中依据。写入失败时本轮回滚，旗下债券由独立任务同步。', '0 15 23 * * ?', 0, '{"poolIds":[17]}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(6, 'company_inpool_bond_auto_in', '在池主体旗下债券自动入池（已排除ABS债）（仅债券）', '1. Demo 每 10 分钟第 1 分执行，默认关闭调度。\n2. poolIds 配置同池，Demo 为 [15,16,17,23]；mappings 用 companyInPoolId 和 bondTargetPoolId 配置跨池。合并规则绑定及已有生效主体的同池范围，兼容旧同池任务配置。\n3. 跟随已生效主体筛选尚未在目标池的普通债及普通池内的 CRMW，排除 ABS、退市债和已转正的临时旧码。minDaysToMaturity 须为非负整数，按摘牌日（delist_date，yyyyMMdd）比较，默认 0 时摘牌当天可入，填 1 时摘牌当天不入。\n4. 普通候选复用手工单券准入，同券、联动、互斥及反向调入限制引起的配套调出整组校验。缺少所需报告豁免的候选跳过并记录原因。\n5. 主体 Excel 调入生效后优先补入，跳过评级、到期天数和材料校验，继续校验池关系与在途流程。主体 Excel 调出后拦截该池回补。\n6. 整组校验通过后由系统自动调整并直接生效，写入池状态及调库日志，按实际入池记录统计。', '0 1/10 * * * ?', 0, '{"poolIds":[15,16,17,23],"minDaysToMaturity":0}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(7, 'company_not_in_pool_bond_auto_out', '出池主体旗下债券自动出池（仅债券）', '1. Demo 每 10 分钟第 3 分执行，默认关闭调度。\n2. poolIds 配置同池，Demo 为 [15,16,17,23]。mappings 用 bondPoolId 和 companyPoolId 配置跨池。按目标池汇总补债映射、历史主体同池、出池参数、规则绑定和联动池等依据。\n3. 扫描普通池中已生效且可识别的普通债和 CRMW 跟随记录。ABS 债及独立 CRMW 组合由各自任务处理。\n4. 符合任一条件即进入出池校验。\n（一）该主体在债券目标池最新的 Excel 调出决定已生效。\n（二）发行主体在所有依据池均无有效留池依据。\n5. 保留来源不清和独立入池记录。命中调出限制池、调出互斥池或在途流程的债券跳过。\n6. 黑名单质押库（17）常规出池时，主体仍在债券禁止库（15）、近一年最低认可外评为 AA- 及以下、仍在重点观察名单（23），满足任一项即留池。主体 Excel 调出触发时跳过三条件复核，仍执行第 5 条。\n7. 撤销符合条件的跟随记录。撤销目标池最后一条有效在池记录时，出池直接生效，写调库日志并计入实际出池。写日志失败时本轮回滚。', '0 3/10 * * * ?', 0, '{"poolIds":[15,16,17,23]}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(8, 'bond_grade_inconformity_alert', '不符合主体债入池规则提醒（含ABS债，担保债取快照担保人内评）（仅债券）', '1. Demo 每天 01:00 执行，无需扩展参数，默认关闭调度。\n2. 扫描已在信用债 1～5 级且不符合当前主体债入池规则的债券，含 ABS 债，不含境外债。\n3. ABS 确认权益人后主体已固定到主档发行人字段，直接取主档发行人内评，不查询入库快照。\n4. 担保债可能对应多个担保人，按当前在池记录的入库快照取当时选定的担保人，再查该担保人最新内评，与发债主体内评取较优档。担保债缺少来源日志、入库快照或担保人代码时，本轮失败并回滚。\n5. 写入待办供人工下调或出库，不自动修改池状态。\n6. 执行摘要区分本轮命中、沿用已处理、本轮失效、仍待处理。\n7. 在「我的事宜」的分级规则提醒中查看或处理，影响条数取仍待处理数。', '0 0 1 * * ?', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(9, 'hs_pool_full_excel_export', '恒生池全量数据导出（不含已到期）', '1. Demo 每天 01:10 执行，默认关闭调度。\n2. poolIds 可限制导出叶子池，未填写时导出全部叶子池。exportEmptyPool 默认 true，设为 false 时跳过无数据的池。\n3. 导出当前已生效的非主体证券和 CRMW；普通证券排除摘牌日早于当天的记录，独立 CRMW 组合不校验摘牌日。\n4. exportPoolWithoutHsName 默认 false，跳过恒生池名称为空的池，设为 true 时使用投资池完整名称生成 Sheet。恒生池名称可用竖线拆分多个 Sheet，名称超过 31 位截断，同名 Sheet 合并并记录警告。\n5. 固定导出证券名称、证券代码、操作类型、市场名称、备注；全量操作类型和备注为空。\n6. 按每条记录的实际市场输出恒生市场编码，证券代码去掉市场后缀。\n7. outputDir 可指定输出根目录，为 null 或省略时使用系统配置。主文件以固定名称写入 yyyyMMdd 日期目录，同日覆盖时旧版归档到 bak，历史文件名带时间戳。FTP 暂未接入。', '0 10 1 * * ?', 0, '{"poolIds":[],"exportEmptyPool":true,"exportPoolWithoutHsName":false,"outputDir":null}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(10, 'hs_pool_full_including_expired_excel_export', '恒生池全量数据导出（含已到期）', '1. Demo 每天 01:20 执行，默认关闭调度。\n2. poolIds 可限制导出叶子池，未填写时导出全部叶子池。exportEmptyPool 默认 true，设为 false 时跳过无数据的池。\n3. 导出当前已生效的非主体证券和 CRMW；普通证券包含已到期数据，独立 CRMW 组合不校验摘牌日。\n4. exportPoolWithoutHsName 默认 false，跳过恒生池名称为空的池，设为 true 时使用投资池完整名称生成 Sheet。恒生池名称可用竖线拆分多个 Sheet，名称超过 31 位截断，同名 Sheet 合并并记录警告。\n5. 固定导出证券名称、证券代码、操作类型、市场名称、备注；全量操作类型和备注为空。\n6. 按每条记录的实际市场输出恒生市场编码，证券代码去掉市场后缀。\n7. outputDir 可指定输出根目录，为 null 或省略时使用系统配置。主文件以固定名称写入 yyyyMMdd 日期目录，同日覆盖时旧版归档到 bak，历史文件名带时间戳。FTP 暂未接入。', '0 20 1 * * ?', 0, '{"poolIds":[],"exportEmptyPool":true,"exportPoolWithoutHsName":false,"outputDir":null}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(17, 'company_observer_pool_sync', '主体观察名单同步（仅主体）', '1. Demo 配置每天 06:00，默认关闭调度。\n2. observePoolId 对应观察类型 2，Demo 为 16（观察池）；keyObservePoolId 对应类型 3，Demo 为 23（重点观察名单）。省略或填 null 时不管理该类池，至少配置一个正整数池 ID，两类池不能相同。\n3. 读取 AIS 主体观察名单，按主体和观察类型匹配目标池。类型变更、类型 1、类型为空或名单移除时退出原池，先出后入。缺少发行主体编码时跳过并记录。\n4. 按池关系处理主体联动、互斥和反向限制池配套调出。调入校验来源池，进出校验对应限制池；命中弹性禁投池时记录警告。涉及 Excel 入池保护的调整跳过。\n5. 主体调整直接生效，写调库日志及池状态。参数或名单校验、池关系校验或写入失败时整轮回滚。旗下债券由独立任务同步。', '0 0 6 * * ?', 0, '{"observePoolId":16,"keyObservePoolId":23}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(15, 'pledge_blacklist_daily_increment_reminder', '质押黑名单库每日增量提醒', '1. Demo 每天 09:00 执行，默认关闭调度。\n2. poolIds 为质押黑名单扫描池，默认 [17]。\n3. 首次从当天 00:00:00 开始，后续以上次成功执行开始时间为水位，以本次执行开始时间为上界，按审核时间扫描审批通过的债券和主体调入调出流水，含下界、不含上界。\n4. 债券摘牌日为空（NULL）或晚于当天时纳入提醒。无增量时生成“当日无增量调整”消息。\n5. 当前通知通道未接入，仅生成候选并写定时任务过程日志，不会误报发送成功。', '0 0 9 * * ?', 0, '{"poolIds":[17]}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(16, 'bond_issuer_not_in_company_pool_reminder', '主体库内债券主体不在池债邮件提醒（仅债券）', '1. Demo 每天 09:00 执行，默认关闭调度。\n2. poolIds 表示债券池与主体池相同；mappings 可分别配置 bondPoolId、companyPoolId；同池与跨池去重合并，未配置参数时默认同池 [15]。\n3. 扫描债券池中已生效、但发行主体不在对应主体池的债券。\n4. 普通债与 ABS 债参与扫描，CRMW 排除。缺失发行主体主数据的债券也进入提醒候选。\n5. 当前通知通道未接入，仅生成候选并写定时任务过程日志，不会误报发送成功。', '0 0 9 * * ?', 0, '{"poolIds":[15]}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(19, 'crmw_rule_alert', 'CRMW规则提醒', '1. Demo 每天 09:13 执行，无需扩展参数，默认关闭调度。\n2. 扫描有效CRMW在池组合，以凭证主档发行主体作为创设方或保护方，按启用档位顺序评估该主体最新内评。\n3. 内评低于3档，或主体在观察池、重点观察名单时生成独立待办，3档本身不触发评级提醒。\n4. 每天按当前风险状态检查，包含存量风险；只提醒，不自动改池。\n5. 同组合、同池、同入库来源和同风险依据已处理时不再提醒；合规或出库后旧待办失效。\n6. 缺少凭证主体、最新内评或有效档位时整轮失败并回滚。', '0 13 9 * * ?', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
(11, 'hs_pool_increment_excel_export', '恒生池增量数据导出', '1. Demo 每 6 分钟执行一次，交易日和非交易日均执行，默认关闭调度。\n2. 首次必填 initialStartTime（yyyy-MM-dd HH:mm:ss）作为下界，后续以上次成功执行开始时间为下界，本次开始时间为上界。审核时间须大于下界且不晚于上界。\n3. 导出窗口内审批通过的普通非主体证券及 CRMW 调入调出事件，排除已失效的临时代码，不要求证券当前仍在池。\n4. 调出操作类型写删除，调入及备注留空。按每条事件的实际市场输出恒生市场编码，证券代码去掉市场后缀。\n5. poolIds 可限制导出的叶子池，省略或为空时导出全部叶子池。exportEmptyPool 默认 true，设为 false 时跳过无数据的池。exportPoolWithoutHsName 默认 false，跳过恒生池名称为空的池，设为 true 时使用投资池完整名称生成 Sheet。\n6. 任务成功时间作为下轮水位，不更新调库日志。outputDir 默认使用系统配置。主文件在 yyyyMMdd 目录固定命名，覆盖前旧版带时间戳归档至 bak。FTP 暂未接入。', '0 */6 * * * ?', 0, '{"poolIds":[],"exportEmptyPool":true,"exportPoolWithoutHsName":false,"outputDir":null,"initialStartTime":"2026-01-01 00:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
-- 每 10 分钟的第 2 分钟执行，会修改池状态，与既有整点及五分钟任务错开
(12, 'wind_code_sync', 'Wind代码变更同步（仅债券）', '1. Demo 每 10 分钟第 2 分执行，默认关闭调度。\n2. scanDays 须为正整数，默认 1 天。由 SQL 按数据库时间往前减 scanDays 天过滤，同一 SEC_ID 先取最新 CHANGE_DATE，同日取最新 OPDATE，旧新码相同时跳过。\n3. 按唯一 SEC_ID 拆分旧临时代码失效主档和新代码主档；official 补登记、temporary 复用登记并转 temp_converted、temp_converted 新增本次登记保留历史；主档缺失特别提示并跳过。\n4. 不逐条重放历史；当前码直接换最新码，复用普通池、CRMW及在途申请转换；原审批与历史终态保留。\n5. 单条换码独立提交，成功写旧新码映射并记录完成事件供去重。失败仅回滚本条，继续处理其他事件。任务会修改池状态，须错开其他调库任务。', '0 2/10 * * * ?', 0, '{"scanDays":1}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
-- 每 10 分钟执行一次（第 5 分起，间隔 10 分钟），与主体入池任务的 0/10/20 分错开；ABS 进出池统一由本任务对账
(18, 'company_abs_bond_auto_in', '主体下ABS债券自动入库（区分已确认发行人和未确认发行人）（仅债券）', '1. Demo 每 10 分钟第 5 分执行，默认关闭调度。\n2. 扫描 poolIds、关系绑定池、已有生效主体或 ABS 的池，范围为空则失败。mappings 用 bondPoolId 与 companyPoolId 配置跨池，覆盖该债券池的同池口径。\n3. Demo 的 enableIn、enableOut 均开启。省略时入池默认关闭、出池默认开启；同时关闭则失败。\n4. 已确认发行人按主档 issuer_code 跟随主体进出池。\n5. enableUnconfirmedIssuerIn 默认关闭；与 enableIn 同时开启时，按担保人、差额支付承诺人、债务主体、原始权益人匹配未确认发行人的 ABS，只生成提醒和待确认日志。\n6. 出池遇到债级独立入池依据、在途流程或未确认 ABS 的其他关联主体仍在池时，只提醒。\n7. 入池按 minDaysToMaturity 过滤，按摘牌日（delist_date，yyyyMMdd）计算，默认 0，含摘牌当天。17 池进出均复核主体三条件，入池校验市场。\n8. 每池先出后入，单池失败只回滚该池。', '0 5/10 * * * ?', 0, '{"enableIn":true,"enableOut":true,"enableUnconfirmedIssuerIn":false,"minDaysToMaturity":0}', NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW()),
-- 每10分钟第7分执行，错开主体补债、Wind换码和ABS对账
(20, 'crmw_forbidden_auto_out', 'CRMW关联禁投自动出库', '1. Demo 每 10 分钟第 7 分执行，无需扩展参数，默认关闭调度。\n2. 一次读取全部有效CRMW在库组合，标的债券、标的发行主体、CRMW凭证、创设方或保护方任一在有效禁止库时清退。\n3. 标的债券由A公司发行，CRMW凭证由B机构创设或提供信用保护，双方主体分别取各自主档 issuer_code。\n4. 只生成系统自动CRMW出库记录，不重复入禁止库，不自动恢复组合。\n5. 每个组合独立事务；单条失败只回滚该条并记录错误，继续其他组合，汇总成功和失败数量。\n6. 禁投硬清退不检查人工锁定、冻结期、开放日、调出限制或到期日；不修改调入校验和最终审批复核。\n7. 主档或双方唯一主体代码缺失时记录该条失败并继续，不推断主体；公共查询异常才使任务失败。', '0 7/10 * * * ?', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NOW(), NOW());
